// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 timestamp1, uint256 timestamp2, uint256 blockNumber1, uint256 blockNumber2) public {
        vm.assume(timestamp1 > 0);
        vm.assume(timestamp2 > timestamp1);
        vm.assume(blockNumber1 > 0);
        vm.assume(blockNumber2 > 0);
        vm.assume(blockNumber1 % 15 != 0);
        vm.assume(blockNumber2 % 15 != 0);
        vm.assume(timestamp2 < type(uint256).max / 2);

        address me = address(this);
        vm.deal(me, 20 ether);

        vm.warp(timestamp1);
        vm.roll(blockNumber1);
        vm.prank(me);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1, "first call failed");

        vm.warp(timestamp2);
        vm.roll(blockNumber2);
        vm.prank(me);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        require(ok2, "second call failed");

        assertTrue(c.pastBlockTime() == timestamp2);
    }
}
